// Extrai URL do webhook
const url = $input.item.json.body.url || $input.item.json.url;

if (!url) {
  throw new Error('URL é obrigatória');
}

return {
  post_url: url
};

const cheerio = require('cheerio');
const html = $input.item.json.data;

if (!html) {
  return {
    error: 'HTML vazio ou inválido',
    url: $('Validate Input').item.json.post_url
  };
}

const $ = cheerio.load(html);

// Extrai title
const title = $('title').text().trim() || 
              $('meta[property="og:title"]').attr('content') || 
              $('h1').first().text().trim() || 
              'Sem título';

// Conta imagens
const num_images = $('img').length;

// Conta vídeos
const num_videos = $('video').length + 
                   $('iframe[src*="youtube"]').length + 
                   $('iframe[src*="vimeo"]').length + 
                   $('iframe[src*="youtu.be"]').length;

// Conta links
const post_url = $('Validate Input').item.json.post_url;
const base_domain = new URL(post_url).hostname;

let num_links_internal = 0;
let num_links_external = 0;

$('a[href]').each((i, elem) => {
  const href = $(elem).attr('href');
  if (!href) return;

  try {
    if (href.startsWith('/') || href.startsWith('#')) {
      num_links_internal++;
    } else if (href.startsWith('http')) {
      const linkDomain = new URL(href).hostname;
      if (linkDomain === base_domain) {
        num_links_internal++;
      } else {
        num_links_external++;
      }
    }
  } catch (e) {
    // Ignora links inválidos
  }
});

// Extrai texto para análise
const bodyText = $('article').text() || 
                 $('main').text() || 
                 $('body').text();
const textPreview = bodyText.replace(/\s+/g, ' ').trim().slice(0, 500);

return {
  url: post_url,
  title: title,
  num_images: num_images,
  num_videos: num_videos,
  num_links_internal: num_links_internal,
  num_links_external: num_links_external,
  text_preview: textPreview,
  html_size: html.length,
  success: true
};

return {
  success: false,
  error: 'Falha ao fazer scraping',
  url: $('Validate Input').item.json.post_url
};
